ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len) {
    struct rdma_mcast *mcast;
    struct rdma_cm_id *id = file->id;
    int ret;

    if (out_len < sizeof(*cmd))
        return -EINVAL;

    if (cmd->addr_len < sizeof(struct sockaddr_in))
        return -EINVAL;

    if (cmd->flags & RDMA_MCAST_JOIN_FLAG)
        return -EINVAL;

    mcast = kmalloc(sizeof(*mcast) + cmd->addr_len, GFP_KERNEL);
    if (!mcast)
        return -ENOMEM;

    mcast->addr_len = cmd->addr_len;
    memcpy(&mcast->addr, &cmd->addr, cmd->addr_len);

    ret = rdma_join_multicast(id, &mcast->addr, cmd->join_flags);
    if (ret) {
        kfree(mcast);
        return ret;
    }

    mcast->context = id->context;
    mcast->qp = id->qp;
    mcast->id = id;

    id->mcast = mcast;
    cmd->group_id = (uintptr_t)mcast;

    return 0;
}

ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len)
{
    struct rdma_ucm_join_mcast_resp resp = {};
    struct rdma_mcast *mcast;
    struct rdma_cm_id *id;
    int ret;

    if (out_len < sizeof(resp))
        return -EINVAL;

    if (cmd->addr_len > sizeof(resp.addr))
        return -EINVAL;

    id = rdma_lookup_id_by_file(file);
    if (!id)
        return -EBADF;

    mcast = kmalloc(sizeof(*mcast), GFP_KERNEL);
    if (!mcast) {
        ret = -ENOMEM;
        goto out;
    }

    mcast->id = id;
    mcast->group = cmd->group;
    mcast->join_state = (cmd->flags & RDMA_MCAST_JOIN_FLAG) ? RDMA_MCAST_JOIN_SILENT : RDMA_MCAST_JOIN_ACTIVE;

    ret = rdma_mcast_join(id, &mcast->group, mcast->join_state);
    if (ret) {
        kfree(mcast);
        goto out;
    }

    resp.addr_len = cmd->addr_len;
    memcpy(&resp.addr, &cmd->addr, cmd->addr_len);
    ret = 0;

    if (copy_to_user((void __user *)cmd, &resp, sizeof(resp)))
        ret = -EFAULT;

    id->mcast = mcast;
out:
    return ret;
}

ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len) {
    struct rdma_ucm_join_mcast_resp resp;
    struct rdma_mcast *mcast;
    struct rdma_cm_id *id = file->id;
    int ret;

    if (out_len < sizeof(resp))
        return -EINVAL;

    if (cmd->addr_len < sizeof(struct sockaddr))
        return -EINVAL;

    if (cmd->flags & RDMA_MCAST_JOIN_FLAG)
        return -EINVAL;

    mcast = kzalloc(sizeof(*mcast), GFP_KERNEL);
    if (!mcast)
        return -ENOMEM;

    mcast->id = id;
    ret = rdma_join_ip_multicast(id, &cmd->addr, cmd->addr_len, mcast);
    if (ret) {
        kfree(mcast);
        return ret;
