ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len)
{
  struct rdma_mcast *mcast;
  struct rdma_cm_id *id;
  int ret;

  if (out_len < sizeof(*cmd))
    return -EINVAL;

  if (cmd->addr_len <= 0)
    return -EINVAL;

  id = rdma_lookup_id_by_file(file->device, file->pd, file->qpn);
  if (!id)
    return -ENOENT;

  mcast = calloc(1, sizeof(*mcast));
  if (!mcast) {
    ret = -ENOMEM;
    goto err_free_id;
  }

  mcast->id = id;
  mcast->group = *(struct sockaddr *) cmd->addr;
  mcast->flags = cmd->flags;

  ret = rdma_join_multicast(id, &mcast->group, mcast->flags);
  if (ret)
    goto err_free_mcast;

  cmd->response = RDMA_UCM_JOIN_SUCCESS;
  if (copy_to_user(cmd, cmd, sizeof(*cmd)))
    ret = -EFAULT;

err_free_mcast:
  free(mcast);
err_free_id:
  rdma_put_id(id);
  return ret;
}

ssize_t ucma_join_multicast(struct ucma_file *file, struct rdma_ucm_join_mcast *cmd, int out_len)
{
    struct rdma_ucm_mcast *mcast;
    struct sockaddr *addr = (struct sockaddr *)&cmd->addr;
    struct rdma_cm_id *id = file->id;
    int ret;

    if (out_len < sizeof(*cmd))
        return -EINVAL;

    if (addr->sa_len < sizeof(struct sockaddr_in))
        return -EINVAL;

    mcast = kmalloc(sizeof(*mcast), GFP_KERNEL);
    if (!mcast)
        return -ENOMEM;

    mcast->id = id;
    memcpy(&mcast->addr, addr, addr->sa_len);
    mcast->flags = cmd->flags;

    ret = rdma_resolve_addr(id, NULL, &mcast->addr, RDMA_MAX_TIMEOUT);
    if (ret) {
        kfree(mcast);
        return ret;
    }

    ret = rdma_join_ip_multicast(id, &mcast->addr, cmd->flags);
    if (ret) {
        kfree(mcast);
        return ret;
    }

    id->context = mcast;

    if (copy_to_user(cmd, cmd, sizeof(*cmd)))
        return -EFAULT;

    return 0;
}
